$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
$null=Preview-Quit;$before=Preview-Data;if($before.Count-lt3){throw 'Data hash fixture incomplete'}
$zip=$global:PreviewDir+'\review.zip';$web=New-Object Net.WebClient;try{$web.DownloadFile('http://10.0.2.2:18767/m6-package-review/Koett-Windows-x86_64.zip',$zip)}finally{$web.Dispose()};Expand-Archive -LiteralPath $zip -DestinationPath ($global:PreviewDir+'\review') -Force
$steps=@();foreach($which in @('previous','current','review')){$r=Preview-Run 'Install' ($global:PreviewDir+'\'+$which+'\Koett-Windows-x86_64');if($r.exit-ne0-or-not$r.json.ok){throw ('Install '+$which+' failed: '+$r.stdout)};$steps+=@{version=$which;result=$r;directories=@(Get-ChildItem ($global:PreviewRoot+'\versions') -Directory|ForEach-Object Name)}}
$state=Get-Content ($global:PreviewRoot+'\current.json') -Raw -Encoding UTF8|ConvertFrom-Json;$versions=@(Get-ChildItem ($global:PreviewRoot+'\versions') -Directory);if($versions.Count-ne2){throw ('Old previews were not pruned: '+$versions.Count)}
$rollback=Preview-Run 'Rollback' '';if($rollback.exit-ne0-or-not$rollback.json.ok){throw 'Rollback failed after pruning'};$again=Preview-Run 'Rollback' '';if($again.exit-ne0-or-not$again.json.ok){throw 'Return from rollback failed'}
$uninstall=Preview-Run 'Uninstall' '';if($uninstall.exit-ne0-or-not$uninstall.json.ok){throw 'Uninstall failed'};$after=Preview-Data;$same=($before.Count-eq$after.Count);foreach($key in $before.Keys){$same=$same-and$before[$key]-eq$after[$key]};$startup=(Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run' -Name Koett -ErrorAction SilentlyContinue).Koett
@{passed=($same-and-not(Test-Path $global:PreviewRoot)-and-not$startup);steps=$steps;state=$state;retained_versions=@($versions|ForEach-Object Name);rollback=$rollback;reactivate=$again;uninstall=$uninstall;before=$before;after=$after;startup=$startup;focus=Get-LabFocus}
